{
 "contract_type": "saas",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Orchard Data Ltd."],
   "quote": "between Northwind Labs, Inc. (\"Northwind\") and Orchard Data Ltd. (\"Orchard\")"
  },
  "counterparty": {
   "value": "Orchard Data Ltd.",
   "quote": "between Northwind Labs, Inc. (\"Northwind\") and Orchard Data Ltd. (\"Orchard\")"
  },
  "effective_date": {
   "value": "2025-03-29",
   "quote": "is effective as of 29 March 2025"
  },
  "term_months": {
   "value": 36,
   "quote": "This Agreement will remain in effect for 3 years from the Effective Date."
  },
  "auto_renewal": {
   "value": true,
   "quote": "Thereafter, this Agreement shall automatically renew for successive one (1) year periods"
  },
  "renewal_notice_days": {
   "value": 60,
   "quote": "unless either Party provides written notice of non-renewal at least sixty (60) days prior to the end of the then-current term"
  },
  "governing_law": {
   "value": "Florida",
   "quote": "the laws of the State of Florida"
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": 15,
   "quote": "Invoices are due 15 days after the invoice date."
  },
  "contract_value": {
   "value": 48000,
   "quote": "The subscription fee is USD 48,000 per year, invoiced annually in advance."
  },
  "termination_for_convenience": {
   "value": false,
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Imogen Carter",
   "email": "imogen.carter@orchard.example",
   "title": "Managing Director",
   "party": "Orchard Data Ltd."
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "high",
   "message": "The contract has no limitation of liability clause, so Northwind's exposure (and Orchard's) is uncapped and no consequential damages exclusion exists.",
   "quote": "This Agreement constitutes the entire agreement between the Parties and supersedes all prior discussions relating to its subject matter."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "Northwind cannot exit the 3-year commitment without cause; termination is only available for uncured material breach.",
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  {
   "id": "auto_renewal_notice_window",
   "severity": "medium",
   "message": "The agreement auto-renews for one-year periods unless non-renewal notice is given 60 days before term end; missing the window commits Northwind to another year at USD 48,000.",
   "quote": "unless either Party provides written notice of non-renewal at least sixty (60) days prior to the end of the then-current term"
  },
  {
   "id": "no_confidentiality_or_data_protection",
   "severity": "medium",
   "message": "There is no confidentiality, data protection or IP clause, leaving Northwind's data shared with the analytics platform unprotected by contract.",
   "quote": "Orchard provides a software as a service analytics platform and Northwind wishes to subscribe."
  },
  {
   "id": "sla_no_remedy_and_undefined_provider",
   "severity": "low",
   "message": "The uptime commitment names an undefined 'Provider' and has no service credits or termination remedy for missed uptime.",
   "quote": "Provider will make the Service available with 99.9% monthly uptime, excluding scheduled maintenance."
  },
  {
   "id": "unsigned_signature_blocks",
   "severity": "low",
   "message": "The signature lines are blank in this copy, so execution is not evidenced.",
   "quote": "By: ____________________"
  }
 ],
 "injection_attempt": false,
 "summary": "Northwind Labs, Inc. subscribes to Orchard Data Ltd.'s analytics platform for USD 48,000 per year over an initial 3-year term from 29 March 2025, auto-renewing yearly unless 60 days' notice is given. The contract is Florida-governed, lacks a liability cap and confidentiality terms, and only allows termination for uncured material breach."
}
